from lib import *
S = SS('w70')
steps = [
    step("不带 EDNS0 的 DNS 报文走 UDP,响应最多 512 字节。根区的 DNSKEY 记录集比这大:不带 EDNS0 通过 UDP 问 1.1.1.1,响应只有 17 字节(= 12 字节头 + 5 字节问题,没有一条记录),标志 QR TC RD RA,TC 位置位——服务器放不下,只回头部和问题,让客户端改用 TCP。用 TCP 重问:响应 842 字节,3 条 DNSKEY,标志里没有 TC;建立连接 270 ms,查询往返 269 ms。", t=tl(S(1)), mark=lidx(S(1), 'UDP(无 EDNS0)', 'TCP 重问'), done=lidx(S(1), 'UDP(无 EDNS0)'), b=bars([['UDP 响应(被截断)', 17, '17 字节'], ['TCP 响应(完整)', 842, '842 字节']], 842, mark=[0], done=[1]), kv=KV([['UDP,无 EDNS0', '17 字节,TC=1,0 条记录'], ['TCP 重问', '842 字节,3 条 DNSKEY'], ['TC 位', '提示改用 TCP']], ['TC 位'])),
    step("EDNS0 的 OPT 伪记录。查询 40 字节,末尾 11 字节就是 OPT:00 00 29 04 d0 00 00 80 00 00 00——00 是名字(根);00 29 = 41 是类型 OPT;04 d0 = 1232 是“类”字段,借来放通告的 UDP 载荷大小;00 是扩展 RCODE,00 是 EDNS 版本;80 00 是原本放 TTL 的标志字段,最高位是 DO(要求 DNSSEC 数据),这里 DO = 1;00 00 是 RDLENGTH = 0,没有任何选项。响应 179 字节,里面也有 OPT,1.1.1.1 通告的 UDP 载荷大小是 1232,DO 位被回显。不论我通告 512、1232 还是 4096,它回的都是 1232。", t=tl(S(2)), mark=lidx(S(2), '查询 40 字节', '响应 179 字节'), done=lidx(S(2), '00 = 名字(根)', '通告 payload=512', '通告 payload=1232', '通告 payload=4096'), kv=KV([['OPT 的“类”', '1232 = UDP 载荷大小'], ['OPT 的“TTL”', '扩展 RCODE / 版本 / 标志(DO)'], ['1.1.1.1 通告', '总是 1232']], ['OPT 的“类”'])),
    step("DNS over TCP 的帧格式:每条消息前加 2 个字节的长度。发出的字节是 00 28 + 40 字节报文(0x0028 = 40)。耗时:UDP 一问一答中位 285 ms(也就是到 1.1.1.1 的网络往返);新建 TCP 连接的一问一答中位 612 ms(约 2 倍:一个往返建立连接,一个往返问答;样本里还出现过 1630、2618 ms 的异常慢);在同一条 TCP 连接上的第 2 问中位 295 ms,回到一个往返。所以 DNS over TCP 的代价主要在建立连接,复用连接就几乎没有额外代价。", t=tl(S(3)), mark=lidx(S(3), 'TCP 新连接', 'TCP 复用连接'), done=lidx(S(3), 'TCP 上发送的字节', 'UDP     '), b=bars([['UDP', 285, '285 ms'], ['TCP 新连接', 612, '612 ms'], ['TCP 复用连接第 2 问', 295, '295 ms']], 612, mark=[1], done=[0, 2]), kv=KV([['帧', '2 字节长度 + 报文'], ['UDP', '285 ms'], ['TCP 新连接', '612 ms(≈2 倍)'], ['TCP 复用', '295 ms']], ['TCP 新连接'])),
    step("一次查询在线路上的包数和字节(抓 en0)。UDP:2 个 IP 包,查询 68 字节、响应 100 字节,共 168 字节(重复 3 次都是 →68U、←100U;第一次抓包里混进了 2 个上一条 TCP 连接收尾的包,是抓包窗口的杂音,不算)。TCP 新连接:10 个 IP 包,共 656 字节,依次是 →SYN(64)、←SYN+ACK(60)、→ACK(52)、→查询(94)、←ACK(52)、←响应(126)、→ACK、→FIN、←FIN、→ACK。同样一次问答,TCP 要多 5 倍的包数、约 4 倍的字节。", t=tl(S(4)), mark=lidx(S(4), 'TCP 新连接', '再重复 UDP 3 次'), done=lidx(S(4), 'UDP:4 个 IP 包'), b=bars([['UDP 包数', 2, '2 个'], ['TCP 包数', 10, '10 个'], ['UDP 字节', 168, '168'], ['TCP 字节', 656, '656']], 656, mark=[1, 3], done=[0, 2]), kv=KV([['UDP 一次问答', '2 包 / 168 字节'], ['TCP 新连接', '10 包 / 656 字节'], ['TCP 多出', '握手 3 + 关闭 4 + 确认']], ['TCP 新连接'])),
    step("大响应与 IP 分片。cloudflare.com 的 TXT 记录集通过 TCP 取回是 2649 字节,microsoft.com 的是 4689 字节,都远超以太网 UDP 能装的 1472 字节(MTU 1500 − IP 头 20 − UDP 头 8)。通告的 EDNS0 载荷是 4096 时:cloudflare.com 的 TXT 只收到 43 字节,TC = 1,回答 0 条;通告 1232:同样 43 字节、TC = 1;microsoft.com 通告 4096:42 字节、TC = 1。线上来自 1.1.1.1 的 IP 包每次都只有 1 个、没有分片。也就是说 1.1.1.1 不论客户端通告多大,都只发不超过 1232 字节的 UDP 响应,更大的用 TC 位叫客户端改走 TCP,从而根本不产生 IP 分片。这符合 2020 年 “DNS flag day” 的建议:EDNS0 载荷设成 1232 左右(= IPv6 最小 MTU 1280 − 40 − 8)。", t=tl(S(5)), mark=lidx(S(5), 'cloudflare.com TXT,通告 payload=4096', 'microsoft.com TXT,通告 payload=4096'), done=lidx(S(5), 'cloudflare.com TXT,通告 payload=1232', '2020 年起'), b=bars([['cloudflare.com TXT(TCP 完整)', 2649, '2649 字节'], ['microsoft.com TXT(TCP 完整)', 4689, '4689 字节'], ['UDP 实际收到', 43, '43 字节 + TC']], 4689, mark=[2], done=[0, 1]), kv=KV([['大响应', '2649~4689 字节(TCP 取回)'], ['UDP 响应', '43 字节,TC=1'], ['分片', '线上 0 个']], ['UDP 响应'])),
]
A = mkartw('w70', 70, '网络协议,DNS,EDNS0,DNS over TCP,TC,OPT,IP 分片,真实验证,动画演示',
    '实测 DNS 的 512 字节限制与 EDNS0:不带 EDNS0 的根 DNSKEY 响应被截成 17 字节并置 TC,TCP 重问得 842 字节;OPT 记录 11 字节里藏着 1232 的载荷大小和 DO 位;TCP 新连接 612 ms 约为 UDP 285 ms 的两倍,线上 10 包对 2 包;1.1.1.1 对 2649 / 4689 字节的响应一律 TC,不产生 IP 分片。',
    'DNS 最早规定 UDP 响应不得超过 512 字节,今天的响应(DNSSEC 签名、一大串 TXT)早就装不下了。这篇看两种办法:EDNS0 让客户端告诉服务器自己能收多大的 UDP 包;或者干脆改用 TCP。再看 TCP 比 UDP 贵多少,以及公共解析器怎么避免产生 IP 分片。',
    [('17 字节', '不带 EDNS0 的根 DNSKEY 查询,UDP 上收到的被截断响应(TC = 1)'), ('285 → 612 ms', 'UDP 与新建 TCP 连接的一问一答耗时中位数,约 2 倍'), ('0 个', '1.1.1.1 对 2649 / 4689 字节的大响应在线上产生的 IP 分片')],
    [('512 字节与 TC', '<p>不带 EDNS0 的 UDP 响应超过 512 字节时,服务器只回头部和问题并置 TC,客户端应改用 TCP。</p>'),
     ('OPT 记录', '<p>EDNS0 的 OPT 伪记录借用“类”字段放 UDP 载荷大小,借用“TTL”字段放扩展 RCODE、版本和 DO 标志,1.1.1.1 总是通告 1232。</p>'),
     ('TCP 的开销', '<p>TCP 消息前加 2 字节长度;新建连接要多一个往返,约 2 倍耗时;复用同一连接则几乎没有额外代价。</p>'),
     ('线上包数', '<p>一次 UDP 问答 2 包 / 168 字节;一次新建 TCP 连接的问答 10 包 / 656 字节。</p>'),
     ('避免分片', '<p>1.1.1.1 不管客户端通告多大都只发不超过 1232 字节的 UDP 响应,更大的置 TC,让客户端改走 TCP。</p>')],
    steps,
    [ENV_W + '。全部向 1.1.1.1 的 53 端口(UDP 和 TCP),en0 抓包;每种耗时只测 6 次,TCP 新连接出现过 1630 / 2618 ms 的异常慢样本(原因没有查);第四节第一次抓包混入 2 个上一条连接收尾的杂包,正文用的是重复 3 次的干净结果',
     '没有验证:真正发生 IP 分片的 DNS 响应(1.1.1.1 把它们全避开了,需要别的服务器;分片在网络上被丢弃的风险没有测);EDNS0 的其它选项(客户端子网 ECS、Cookie、Padding、NSID)在本篇都没有出现;TCP Fast Open、TCP 保活对 DNS over TCP 的影响;服务器发起关闭 TCP 连接的空闲超时'],
    'DNS over TCP 与 EDNS0')
